// pnpm pages:gen
// Reports which generated pages the current waves produce, which the
// thin-page and near-duplicate guard skips and why. The pages themselves are
// generated by the build from config/waves.json; this is the report.

const { liveAmounts, currentWave } = await import('../src/lib/pages.ts');
const { guardReport } = await import('../src/lib/salaryPage.ts');

const asAt = process.env.BUILD_DATE ?? new Date().toISOString().slice(0, 10);
let total = 0;
for (const family of ['salary', 'hourly', 'monthly']) {
	const amounts = liveAmounts(family);
	console.log(`${family}: wave ${currentWave(family)}, ${amounts.length} page(s)`);
	if (family !== 'salary' || !amounts.length) continue;
	const report = guardReport(amounts, asAt);
	for (const r of report) {
		if (r.ok) total++;
		else console.log(`  skipped /salary/${r.amount}/: ${r.reason}`);
	}
	console.log(`  ${report.filter((r) => r.ok).length} built, ${report.filter((r) => !r.ok).length} skipped`);
}
console.log(`${total} generated page(s) in all`);
